import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for GaussianFitter#fit().
 */
public class GaussianFitter_fit_TriageGen4Test {

    private LevenbergMarquardtOptimizer optimizer;

    @Before
    public void setUp() {
        optimizer = new LevenbergMarquardtOptimizer();
    }

    @Test
    public void testFitWithValidData() {
        // Create synthetic Gaussian data: y = amplitude * exp(-(x-mean)^2 / (2 * sigma^2))
        // Let amplitude = 10, mean = 5, sigma = 2
        WeightedObservedPoints points = new WeightedObservedPoints();
        for (double x = 0; x <= 10; x += 0.5) {
            double y = 10 * Math.exp(-Math.pow(x - 5, 2) / (2 * Math.pow(2, 2)));
            points.add(x, y);
        }

        GaussianFitter fitter = new GaussianFitter(optimizer, points.getWeightedObservedPoints());

        // Execute the method under test
        double[] parameters = fitter.fit();

        // Assertions
        assertNotNull("The returned parameters array should not be null", parameters);
        // Gaussian parameters: [amplitude, mean, sigma]
        assertTrue("Parameters array should have length 3", parameters.length == 3);

        // Check if the fitted parameters are reasonably close to the true values
        // Note: due to numerical optimization, we check for approximate correctness
        assertTrue("Amplitude should be near 10", Math.abs(parameters[0] - 10) < 1.0);
        assertTrue("Mean should be near 5", Math.abs(parameters[1] - 5) < 0.5);
        assertTrue("Sigma should be near 2", Math.abs(parameters[2] - 2) < 0.5);
    }

    @Test(expected = Exception.class)
    public void testFitWithInsufficientData() {
        // Gaussian fitting requires a minimum number of points to be mathematically solvable
        WeightedObservedPoints points = new WeightedObservedPoints();
        points.add(1.0, 1.0); // Only one point

        GaussianFitter fitter = new GaussianFitter(optimizer, points.getWeightedObservedPoints());

        // This should trigger an exception during the optimization process or parameter guessing
        fitter.fit();
    }

    @Test
    public void testFitCallsInternalFitWithGuess() {
        // This test ensures that the fit() method correctly leverages the underlying logic
        // by providing a data set where the result is predictable.
        WeightedObservedPoints points = new WeightedObservedPoints();
        // Flat line (very low amplitude)
        for (double x = 0; x <= 10; x += 1.0) {
            points.add(x, 0.0001);
        }

        GaussianFitter fitter = new GaussianFitter(optimizer, points.getWeightedObservedPoints());
        double[] parameters = fitter.fit();

        assertNotNull(parameters);
        assertTrue(parameters.length == 3);
    }
}
